typeScriptFunctionUsageExample:
import { areWeakMaps } from "@type-check/guards";

const list: unknown[] = [new WeakMap<object, number>(), new WeakMap<object, number>()];

if (areWeakMaps(list)) {
  // list is a non-empty array of WeakMap instances
  for (const wm of list) {
    wm.set({}, 1);
  }
} else {
  // not a non-empty WeakMap[]
}

typeScriptObjectUsageExample:
import { areWeakMaps } from "@type-check/guards";

type Config = { caches: unknown };

const cfg: Config = { caches: [new WeakMap<object, string>()] };

if (!areWeakMaps(cfg.caches as unknown[])) {
  throw new TypeError("caches must be a non-empty array of WeakMap instances");
}

// Safe to use as WeakMap[] here
cfg.caches[0].set({}, "ok");
